下面是同事写的运费计算函数（TypeScript，已简化）：

```ts
export async function calcShipping(orderId: string): Promise<number> {
  const order = await orderClient.get(orderId);
  const addr = await addressClient.resolve(order.addressId);
  let fee = 0;
  if (addr.region === "remote") fee += 1500;
  const weight = order.items.reduce((s, i) => s + i.weightGram * i.qty, 0);
  if (weight > 20000) fee += Math.ceil((weight - 20000) / 1000) * 80;
  const promo = await promoClient.getActive(order.userId);
  if (promo?.type === "free_shipping" && fee <= 3000) fee = 0;
  if (order.channel === "wholesale") fee = Math.floor(fee * 0.6);
  return fee;
}
```

